package org.brightstats.stats;
import java.util.*;
import java.util.function.IntConsumer;

/** Shared PLS/GSCA stage followed by an adjusted-copula polynomial equation system. */
public final class ComponentAdjustedCopula {
    private ComponentAdjustedCopula(){}
    public record Specification(AdjustedCopula.Model system,Map<Integer,Integer> binaryBindings){public Specification{Objects.requireNonNull(system);binaryBindings=Collections.unmodifiableMap(new LinkedHashMap<>(binaryBindings));for(var entry:binaryBindings.entrySet())if(entry.getKey()<0||entry.getValue()<0)throw new IllegalArgumentException("Binary bindings must use nonnegative component/data indices.");}}
    public record Fit(ComponentScores.Fit firstStage,Specification specification,AdjustedCopula.Fit correction,List<String> warnings){public Fit{warnings=List.copyOf(warnings);}}
    public record Resampled(Fit point,Bootstrap.Result inference,List<CopulaWald.Result> wald){public Resampled{wald=List.copyOf(wald);}}
    public static Fit fit(double[][] data,ComponentScores.Model supplied,Specification specification){var model=complete(supplied,specification);validate(data,model,specification);var stage=ComponentScores.fit(data,model);return describe(data,stage,specification,stage.scores(),null);}
    private static ComponentScores.Model complete(ComponentScores.Model model,Specification specification){var system=specification.system;if(!model.names().equals(system.names()))throw new IllegalArgumentException("Component/system names and order must agree.");var paths=NonlinearPls.normalizedPaths(system.names(),system.paths(),system.extensions());var stagePaths=NonlinearPls.normalizedPaths(model.names(),model.paths(),system.extensions());if(!new HashSet<>(paths).equals(new HashSet<>(stagePaths)))throw new IllegalArgumentException("Component and correction structural paths must agree after explicit polynomial hierarchy completion.");if(model.estimator()==ComponentScores.Estimator.PLS)return ComponentScores.Model.pls(model.blocks(),paths,model.plsOptions());var original=model.gscaModel();boolean[][] graph=new boolean[model.names().size()][model.names().size()];for(var path:paths)graph[path.source()][path.target()]=true;return ComponentScores.Model.gsca(new Gsca.Model(original.indicators(),original.components(),original.weights(),original.loadings(),graph,original.initialWeights()),model.gscaOptions(),model.gscaColumns());}
    private static void validate(double[][] data,ComponentScores.Model model,Specification specification){int width=Matrices.width(data,3);Set<Integer> binary=new HashSet<>();for(var correction:specification.system.corrections())for(int col:correction.binaryExogenous())binary.add(col);if(!binary.equals(specification.binaryBindings.keySet()))throw new IllegalArgumentException("Bind every declared binary component, and no other component, to its original 0/1 data column.");for(var entry:specification.binaryBindings.entrySet()){int component=entry.getKey(),column=entry.getValue();if(component>=model.names().size()||column>=width)throw new IllegalArgumentException("Binary binding is outside the component/data schema.");if(model.estimator()==ComponentScores.Estimator.PLS){int[] indicators=model.blocks().get(component).columns();if(indicators.length!=1||indicators[0]!=column)throw new IllegalArgumentException("A binary PLS covariate must be a single-indicator component bound to that same raw column.");}else{boolean[][] weights=model.gscaModel().weights();int found=-1,count=0;for(int i=0;i<weights.length;i++)if(weights[i][component]){found=i;count++;}if(count!=1||model.gscaColumns()[found]!=column)throw new IllegalArgumentException("A binary GSCA covariate must have exactly one weight indicator bound to its raw column.");}for(var row:data)if(row[column]!=0&&row[column]!=1)throw new IllegalArgumentException("Binary raw data must be coded 0/1.");}}
    private static Fit describe(double[][] data,ComponentScores.Fit stage,Specification specification,double[][] aligned,AdjustedCopula.Fit reference){for(var binding:specification.binaryBindings.entrySet())for(int row=0;row<data.length;row++)aligned[row][binding.getKey()]=data[row][binding.getValue()];var system=specification.system;var normalized=new AdjustedCopula.Model(system.names(),stage.model().paths(),system.extensions(),system.corrections(),reference==null?system.probes():reference.model().probes());var correction=AdjustedCopula.refit(aligned,normalized,reference);List<String>warnings=new ArrayList<>(stage.warnings());warnings.addAll(correction.warnings());warnings.add("The component stage is refitted once per shared observation draw; all selected equations use those same aligned scores. Polynomial lower-order paths are included in the component stage. This is two-stage score-based correction, not joint latent-variable maximum likelihood.");if(!specification.binaryBindings.isEmpty())warnings.add("Explicit single-indicator binary covariates use their original 0/1 values in the downstream system, replacing standardized component proxies only for those declared roots.");return new Fit(stage,new Specification(correction.model(),specification.binaryBindings),correction,warnings);}
    public static Resampled bootstrap(double[][] data,ComponentScores.Model model,Specification specification,Bootstrap.Options options,IntConsumer progress){Fit point=fit(data,model,specification);var original=point.firstStage.scores();var completed=point.firstStage.model();var wald=new CopulaWald.Accumulator(point.correction,options.samples());var inference=Resampling.run(data,AdjustedCopula.parameters(point.correction),AdjustedCopula.values(point.correction),options,(sample,rows)->{var stage=ComponentScores.fit(sample,completed);double[][] aligned=ComponentScores.align(stage.scores(),original,rows);double[] values=AdjustedCopula.values(describe(sample,stage,point.specification,aligned,point.correction).correction);if(sample.length==data.length)wald.accept(values);return values;},progress,"Full-pipeline "+model.estimator()+" adjusted-copula polynomial system","Every shared case/jackknife draw refits the complete component stage, aligns all scores at sampled original-row indices, restores declared raw binary roots, regenerates all conditional adjusted controls and refits every equation with frozen point-fit probes/categories.");List<String>warnings=new ArrayList<>(inference.warnings());warnings.addAll(point.warnings);inference=new Bootstrap.Result(inference.options(),inference.method(),inference.randomGenerator(),inference.signHandling(),inference.successful(),inference.failed(),inference.failures(),inference.estimates(),warnings,inference.estimator());return new Resampled(point,inference,wald.finish(inference.successful()));}
}
